import{_ as d,o as e,c as o,a3 as a}from"./chunks/framework.BM_-pWjS.js";const p=JSON.parse('{"title":"写真を評価する","description":"","frontmatter":{},"headers":[],"relativePath":"ja/rating.md","filePath":"ja/rating.md"}'),r={name:"ja/rating.md"};function c(h,t,i,n,l,s){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="写真を評価する" tabindex="-1">写真を評価する <a class="header-anchor" href="#写真を評価する" aria-label="Permalink to &quot;写真を評価する&quot;">​</a></h1><p>bridge-lite の評価・ラベル情報は <strong>XMP 形式</strong>で書き込まれます。JPEG はデフォルトでファイル内に直接埋め込まれ、RAW はサイドカーファイル（<code>.xmp</code>）に書き込まれます。JPEG はサイドカー方式に変更することもできます（設定から変更可能）。Lightroom・Capture One・Adobe Bridge とそのまま互換します。</p><h2 id="星評価" tabindex="-1">星評価 <a class="header-anchor" href="#星評価" aria-label="Permalink to &quot;星評価&quot;">​</a></h2><p>0〜5 の星評価を<strong>キーボードショートカット</strong>または<strong>右クリックメニュー</strong>から付けられます。評価値は XMP の <code>xmp:Rating</code> フィールドに書き込まれます。このフィールドは Lightroom・Capture One・Adobe Bridge・FastRawViewer など多くのソフトウェアで共通して読み書きされる標準フィールドです。</p><h3 id="ショートカット" tabindex="-1">ショートカット <a class="header-anchor" href="#ショートカット" aria-label="Permalink to &quot;ショートカット&quot;">​</a></h3><p>ショートカットは設定ページの <strong>評価 / ラベルキー</strong> から変更できます。</p><table tabindex="0"><thead><tr><th>設定値</th><th>ショートカット</th></tr></thead><tbody><tr><td>数字キー</td><td><code>0</code>〜<code>9</code></td></tr><tr><td>⌘ + 数字</td><td><code>⌘0</code>〜<code>⌘9</code></td></tr><tr><td>^ + 数字</td><td><code>^0</code>〜<code>^9</code></td></tr></tbody></table><table tabindex="0"><thead><tr><th>キー</th><th>評価</th></tr></thead><tbody><tr><td><code>0</code></td><td>評価なし</td></tr><tr><td><code>1</code></td><td>★☆☆☆☆</td></tr><tr><td><code>2</code></td><td>★★☆☆☆</td></tr><tr><td><code>3</code></td><td>★★★☆☆</td></tr><tr><td><code>4</code></td><td>★★★★☆</td></tr><tr><td><code>5</code></td><td>★★★★★</td></tr></tbody></table><h3 id="右クリックメニュー" tabindex="-1">右クリックメニュー <a class="header-anchor" href="#右クリックメニュー" aria-label="Permalink to &quot;右クリックメニュー&quot;">​</a></h3><p>サムネイルを右クリック → <strong>評価</strong> から同じ操作が行えます。マウス操作のみで完結させたい場合に便利です。</p><h2 id="グループ写真への評価" tabindex="-1">グループ写真への評価 <a class="header-anchor" href="#グループ写真への評価" aria-label="Permalink to &quot;グループ写真への評価&quot;">​</a></h2><p>バースト撮影などでグループ化された写真に評価を付けると、<strong>グループ内の全カットに同じ評価が伝搬します</strong>（デフォルト動作）。個別のカットだけ評価を調整したい場合は、メタデータバーから操作します。</p><p>詳細な動作・操作手順は<a href="./rating-spec.html">評価の伝搬</a>を参照してください。</p><h2 id="カラーラベル" tabindex="-1">カラーラベル <a class="header-anchor" href="#カラーラベル" aria-label="Permalink to &quot;カラーラベル&quot;">​</a></h2><p>ラベル情報は <code>xmp:Label</code> および <code>photoshop:LabelColor</code> に書き込まれます（Adobe Bridge 互換）。カラーラベルは<strong>ショートカット</strong>または<strong>右クリックメニュー</strong>から設定できます。</p><table tabindex="0"><thead><tr><th>キー</th><th>ラベル</th></tr></thead><tbody><tr><td><code>6</code></td><td>赤</td></tr><tr><td><code>7</code></td><td>黄</td></tr><tr><td><code>8</code></td><td>緑</td></tr><tr><td><code>9</code></td><td>青</td></tr><tr><td>—</td><td>紫（ショートカット未割り当て）</td></tr></tbody></table><p>紫は右クリックメニューまたはメタデータバーから設定できます。</p><h2 id="xmp-の保存先" tabindex="-1">XMP の保存先 <a class="header-anchor" href="#xmp-の保存先" aria-label="Permalink to &quot;XMP の保存先&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ファイル種別</th><th>デフォルト</th><th>オプション</th></tr></thead><tbody><tr><td>JPEG</td><td>ファイルに直接埋め込み</td><td>サイドカー（<code>.xmp</code>）に変更可</td></tr><tr><td>RAW（<code>.arw</code> / <code>.cr3</code> など）</td><td>同名の <code>.xmp</code> サイドカー</td><td>—</td></tr></tbody></table><h2 id="lightroom-への引き継ぎ" tabindex="-1">Lightroom への引き継ぎ <a class="header-anchor" href="#lightroom-への引き継ぎ" aria-label="Permalink to &quot;Lightroom への引き継ぎ&quot;">​</a></h2><p>bridge-lite でレーティングを付けた後、Lightroom でフォルダを開くと評価がそのまま反映されます（XMP の自動読み込みが有効な場合）。</p>',21)])])}const g=d(r,[["render",c]]);export{p as __pageData,g as default};
